package com.blog.service.impl; import com.blog.dto.PostDtos.*; import com.blog.entity.*; import com.blog.exception.ApiExceptions.UnauthorizedException; import com.blog.mapper.BlogMapper; import com.blog.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class PostServiceImplTest {@Mock PostRepository posts;@Mock UserRepository users;@Mock CategoryRepository categories;@Mock BlogMapper mapper;@InjectMocks PostServiceImpl service;@Test void updateRejectsNonOwner(){var owner=User.builder().id(1L).email("owner@example.com").role(Role.AUTHOR).build();var requester=User.builder().id(2L).email("other@example.com").role(Role.AUTHOR).build();var post=Post.builder().id(9L).author(owner).build();when(posts.findById(9L)).thenReturn(Optional.of(post));when(users.findByEmail("other@example.com")).thenReturn(Optional.of(requester));assertThrows(UnauthorizedException.class,()->service.update(9L,new PostRequest("A valid title","This content is long enough for validation.",null,false,null),"other@example.com"));}@Test void adminCanDeleteAnyPost(){var owner=User.builder().id(1L).email("owner@example.com").role(Role.AUTHOR).build();var admin=User.builder().id(2L).email("admin@example.com").role(Role.ADMIN).build();var post=Post.builder().id(9L).author(owner).build();when(posts.findById(9L)).thenReturn(Optional.of(post));when(users.findByEmail("admin@example.com")).thenReturn(Optional.of(admin));service.delete(9L,"admin@example.com");verify(posts).delete(post);}}
